# ---- always: second launcher icon "AHbsolute ⚙" (opens AHbsoluteStandaloneActivity: avatar shape, etc.) ----
def patch_manifest():
    for root, dirs, files in os.walk(UP):
        dirs[:] = [d for d in dirs if d not in ("build", ".git", ".gradle", "node_modules")]
        if "AndroidManifest.xml" not in files:
            continue
        mp = os.path.join(root, "AndroidManifest.xml")
        t = read(mp)
        if "org.telegram.ui.LaunchActivity" in t and "</application>" in t:
            if "AHbsoluteStandaloneActivity" in t:
                return True
            act = (
                '    <activity android:name="org.telegram.messenger.ahbsolute.AHbsoluteStandaloneActivity"\n'
                '        android:exported="true"\n'
                '        android:label="AHbsolute \u2699"\n'
                '        android:taskAffinity="' + PKG + '.ahbsettings"\n'
                '        android:theme="@android:style/Theme.Material.Light.NoActionBar">\n'
                '        <intent-filter>\n'
                '            <action android:name="android.intent.action.MAIN" />\n'
                '            <category android:name="android.intent.category.LAUNCHER" />\n'
                '        </intent-filter>\n'
                '    </activity>\n')
            write(mp, t.replace("</application>", act + "</application>", 1))
            return True
    return False

if patch_manifest():
    features["standalone"] = True
    print("ok: second launcher icon 'AHbsolute \u2699' added")
else:
    print("WARN: AndroidManifest.xml with LaunchActivity not found, second launcher icon skipped")

